INSERT OR IGNORE INTO constants (id, category, name, value, numeric_value, applies_to, page_ref, version_year) VALUES ('CONST-185', 'deductible', '가축재해보험 폭염·전기적·질병위험 특약 자기부담금 한도 (원)', '2000000', 2000000.0, '가축재해보험 폭염·전기적·질병위험 특약 자기부담금 한도 (원)', 'p.678', 2026);
